```verilog
module i2c_master (
    input  wire        clk,
    input  wire        rst,
    input  wire [6:0]  s_axis_cmd_address,
    input  wire        s_axis_cmd_start,
    input  wire        s_axis_cmd_read,
    input  wire        s_axis_cmd_write,
    input  wire        s_axis_cmd_write_multiple,
    input  wire        s_axis_cmd_stop,
    input  wire        s_axis_cmd_valid,
    output wire        s_axis_cmd_ready,
    input  wire [7:0]  s_axis_data_tdata,
    input  wire        s_axis_data_tvalid,
    output wire        s_axis_data_tready,
    input  wire        s_axis_data_tlast,
    output wire [7:0]  m_axis_data_tdata,
    output wire        m_axis_data_tvalid,
    input  wire        m_axis_data_tready,
    output wire        m_axis_data_tlast,
    input  wire        scl_i,
    output wire        scl_o,
    output wire        scl_t,
    input  wire        sda_i,
    output wire        sda_o,
    output wire        sda_t,
    output wire        busy,
    output wire        bus_control,
    output wire        bus_active,
    output wire        missed_ack,
    input  wire [15:0] prescale,
    input  wire        stop_on_idle
);

    reg [6:0] address;
    reg [7:0] data;
    reg [2:0] state;
    reg [15:0] scl_count;
    reg [7:0] bit_count;
    reg start;
    reg stop;
    reg read;
    reg write;
    reg write_multiple;
    reg ack;
    reg busy_reg;
    reg bus_control_reg;
    reg bus_active_reg;
    reg missed_ack_reg;

    assign s_axis_cmd_ready = (state == 3'd0);
    assign s_axis_data_tready = (state == 3'd2);
    assign m_axis_data_tdata = data;
    assign m_axis_data_tvalid = (state == 3'd4);
    assign m_axis_data_tlast = (bit_count == 8'd0);
    assign scl_o = (state == 3'd1) || (state == 3'd2) || (state == 3'd3);
    assign scl_t = 1'b0;
    assign sda_o = (state == 3'd1) || (state == 3'd2) || (state == 3'd3);
    assign sda_t = 1'b0;
    assign busy = busy_reg;
    assign bus_control = bus_control_reg;
    assign bus_active = bus_active_reg;
    assign missed_ack = missed_ack_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= 3'd0;
            scl_count <= 16'd0;
            bit_count <= 8'd0;
            start <= 1'b0;
            stop <= 1'b0;
            read <= 1'b0;
            write <= 1'b0;
            write_multiple <= 1'b0;
            ack <= 1'b1;
            busy_reg <= 1'b0;
            bus_control_reg <= 1'b0;
            bus_active_reg <= 1'b0;
            missed_ack_reg <= 1'b0;
            address <= 7'd0;
            data <= 8'd0;
        end else begin
            case (state)
                3'd0: begin
                    if (s_axis_cmd_valid) begin
                        address <= s_axis_cmd_address;
                        start <= s_axis_cmd_start;
                        stop <= s_axis_cmd_stop;
                        read <= s_axis_cmd_read;
                        write <= s_axis_cmd_write;
                        write_multiple <= s_axis_cmd_write_multiple;
                        state <= 3'd1;
                        busy_reg <= 1'b1;
                        bus_control_reg <= 1'b1;
                        bus_active_reg <= 1'b1;
                    end
                end
                3'd1: begin
                    if (scl_count == prescale) begin
                        scl_count <= 16'd0;
                        if (start) begin
                            sda_o <= 1'b0;
                            scl_o <= 1'b0;
                            state <= 3'd2;
                        end else if (stop) begin
                            sda_o <= 1'b1;
                            scl_o <= 1'b1;
                            state <= 3'd0;
                            busy_reg <= 1'b0;
                            bus_control_reg <= 1'b0;
                            bus_active_reg <= 1'b0;
                        end else if (read) begin
                            sda_o <= 1'b1;
                            scl_o <= 1'b1;
                            state <= 3'd3;
                        end else if (write) begin
                            sda_o <= 1'b0;
                            scl_o <= 1'b1;
                            state <= 3'd2;
                        end
                    end else begin
                        scl_count <= scl_count + 16'd1;
                    end
                end
                3'd2: begin
                    if (scl_count == prescale) begin
                        scl_count <= 16'd0;
                        if (write) begin
                            if (s_axis_data_tvalid) begin
                                data <= s_axis_data_tdata;
                                sda_o <= data[7];
                                scl_o <= 1'b0;
                                state <= 3'd3;
                                bit_count <= 8'd7;
                            end
                        end else if (write_multiple) begin
                            if (s_axis_data_tvalid) begin
                                data <= s_axis_data_tdata;
                                sda_o <= data[7];
                                scl_o <= 1'b0;
                                state <= 3'd3;
                                bit_count <= 8'd7;
                            end
                        end
                    end else begin
                        scl_count <= scl_count + 16'd1;
                    end
                end
                3'd3: begin
                    if (scl_count == prescale) begin
                        scl_count <= 16'd0;
                        if (read) begin
                            data[7 - bit_count] <= sda_i;
                            scl_o <= 1'b1;
                            if (bit_count == 8'd0) begin
                                state <= 3'd4;
                            end else begin
                                bit_count <= bit_count - 8'd1;
                                scl_o <= 1'b0;
                            end
                        end else if (write) begin
                            ack <= sda_i;
                            scl_o <= 1'b1;
                            if (bit_count == 8'd0) begin
                                state <= 3'd1;
                                if (!ack) begin
                                    missed_ack_reg <= 1'b1;
                                end
                            end else begin
                                bit_count <= bit_count - 8'd1;
                                scl_o <= 1'b0;
                                data <= data << 1;
                                sda_o <= data[7];
                            end
                        end else if (write_multiple) begin
                            ack <= sda_i;
                            scl_o <= 1'b1;
                            if (bit_count == 8'd0) begin
                                state <= 3'd1;
                                if (!ack) begin
                                    missed_ack_reg <= 1'b1;
                                end
                            end else begin
                                bit_count <= bit_count - 8'd1;
                                scl_o <= 1'b0;
                                data <= data << 1;
                                sda_o <= data[7];
                            end
                        end
                    end else begin
                        scl_count <= scl_count + 16'd1;
                    end
                end
                3'd4: begin
                    if (m_axis_data_tready) begin
                        state <= 3'd1;
                        m_axis_data_tvalid <= 1'b1;
                        m_axis_data_tlast <= 1'b1;
                    end
                end
                default: state <= 3'd0;
            endcase
        end
    end

endmodule
